using System.Linq;

public static class CountPositiveNumbers
{
    public static int CountPositiveNumbers(int[] values)
    {
        return values.Count(value => value >= 0);
    }
}

solutionCode:
using System.Linq;

public static class CountPositiveNumbers
{
    public static int CountPositiveNumbers(int[] values)
    {
        return values.Count(value => value > 0);
    }
}
